// ---------------------------------------------------------------------------
// Accounts, email verification, sessions and the credit ledger.
//
// Rules enforced here:
//   * Every user must sign up with a real email address.
//   * Free credits are granted ONLY after the emailed code is entered.
//   * No document can be generated by an unverified account.
//   * Disposable / temporary email domains are refused at signup.
//
// Passwords are hashed with scrypt from Node's built-in crypto module — no
// extra dependency, and the plain password is never stored.
//
// Storage is a JSON file (accounts-data.json). Everything that touches storage
// is in this file, so moving to a real database later means changing only this.
// ---------------------------------------------------------------------------

const fs = require('fs')
const path = require('path')
const crypto = require('crypto')
const dns = require('dns').promises
const { isDisposableDomain } = require('./disposable-domains.js')

// Where data lives. On a host with an ephemeral filesystem (Render's free tier
// and most defaults) the app directory is WIPED on every redeploy — set
// DATA_DIR to a mounted persistent disk, e.g. DATA_DIR=/var/data
const DATA_DIR = process.env.DATA_DIR || __dirname
if (!fs.existsSync(DATA_DIR)) fs.mkdirSync(DATA_DIR, { recursive: true })

const DATA_FILE = path.join(DATA_DIR, 'accounts-data.json')

// Free credits granted when (and only when) the email is verified.
const FREE_TRIAL_CREDITS = 2
const PRICE_PER_CREDIT_PKR = 100

const VERIFY_CODE_MINUTES = 15     // verification code lifetime
const VERIFY_MAX_ATTEMPTS = 5      // wrong guesses before a code stops working
const VERIFY_RESEND_SECONDS = 60   // minimum gap between codes
const VERIFY_MAX_SENDS_PER_HOUR = 5
const SESSION_DAYS = 60            // how long a login lasts

const PACKAGES = [
  { id: 'single', credits: 1, bonus: 0, label: 'Single document' },
  { id: 'small', credits: 5, bonus: 0, label: 'Occasional' },
  { id: 'medium', credits: 10, bonus: 1, label: 'Regular' },
  { id: 'large', credits: 25, bonus: 4, label: 'Busy practice' },
  { id: 'bulk', credits: 50, bonus: 10, label: 'Chamber' },
]

// --- storage ---------------------------------------------------------------

// A missing file means a brand-new install. An unreadable one must STOP the
// request: treating it as empty would let the next write erase every account.
function readAll() {
  if (!fs.existsSync(DATA_FILE)) return { accounts: {}, byEmail: {} }
  const parsed = JSON.parse(fs.readFileSync(DATA_FILE, 'utf8'))
  if (!parsed || !parsed.accounts) throw new Error('Accounts file has no accounts section')
  return parsed
}

// Throws on failure, so a credit change is never reported as saved when it wasn't.
function writeAll(db) {
  const tmp = DATA_FILE + '.tmp'
  fs.writeFileSync(tmp, JSON.stringify(db, null, 2), 'utf8')
  fs.renameSync(tmp, DATA_FILE)
  return true
}

// Refuse to start on a damaged file rather than fail on every request.
readAll()

const nowIso = () => new Date().toISOString()
const randomId = (p) => p + '_' + crypto.randomBytes(16).toString('hex')

// --- passwords -------------------------------------------------------------

function hashPassword(password) {
  const salt = crypto.randomBytes(16).toString('hex')
  const hash = crypto.scryptSync(password, salt, 64).toString('hex')
  return `${salt}:${hash}`
}

function verifyPassword(password, stored) {
  try {
    const [salt, hash] = String(stored || '').split(':')
    if (!salt || !hash) return false
    const test = crypto.scryptSync(password, salt, 64)
    const known = Buffer.from(hash, 'hex')
    // Constant-time compare, so an attacker can't learn the hash by timing.
    return known.length === test.length && crypto.timingSafeEqual(known, test)
  } catch (e) {
    return false
  }
}

// --- email validation ------------------------------------------------------

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[a-z]{2,}$/i

// Providers where +tags and dots resolve to the SAME inbox. Without this,
// one Gmail account could claim free credits over and over.
const ALIAS_PROVIDERS = new Set([
  'gmail.com', 'googlemail.com', 'outlook.com', 'hotmail.com', 'live.com', 'proton.me', 'protonmail.com',
])

// Returns the canonical form used for uniqueness checks. The address the user
// typed is still what we send mail to; this is only for "is this the same
// inbox?" comparisons.
function canonicalEmail(email) {
  const addr = String(email || '').trim().toLowerCase()
  const at = addr.lastIndexOf('@')
  if (at < 1) return addr
  let local = addr.slice(0, at)
  const domain = addr.slice(at + 1)

  if (ALIAS_PROVIDERS.has(domain)) {
    local = local.split('+')[0]                       // drop +tag
    if (domain === 'gmail.com' || domain === 'googlemail.com') {
      local = local.replace(/\./g, '')                 // dots are ignored by Gmail
    }
  }
  return local + '@' + (domain === 'googlemail.com' ? 'gmail.com' : domain)
}

// Checks the address is well formed, not disposable, and that the domain can
// actually receive mail. Returns { ok } or { ok: false, error }.
async function validateEmail(email) {
  const addr = String(email || '').trim().toLowerCase()

  if (!addr || !EMAIL_RE.test(addr)) {
    return { ok: false, error: 'Please enter a valid email address.' }
  }
  if (addr.length > 254) {
    return { ok: false, error: 'That email address is too long.' }
  }

  const domain = addr.split('@')[1]

  if (isDisposableDomain(domain)) {
    return {
      ok: false,
      error:
        'Temporary or disposable email addresses are not accepted. Please sign up with a permanent address.',
    }
  }

  // Does the domain actually accept mail? This catches typos and throwaway
  // domains that aren't on the blocklist yet. If DNS itself is unreachable we
  // allow the signup through rather than locking out real customers.
  try {
    const mx = await dns.resolveMx(domain)
    if (!mx || mx.length === 0) {
      return { ok: false, error: 'That email domain cannot receive mail. Please check the address.' }
    }
  } catch (err) {
    if (err && (err.code === 'ENOTFOUND' || err.code === 'ENODATA')) {
      return { ok: false, error: 'That email domain does not exist. Please check the address.' }
    }
    // Any other DNS problem (timeout, no network): don't punish the customer.
  }

  return { ok: true, email: addr }
}

// --- signup / verification -------------------------------------------------

// Codes sent to this account within the last hour, oldest first.
function recentVerifySends(acct) {
  const cutoff = Date.now() - 3600 * 1000
  return (acct.verifySends || []).filter((at) => new Date(at).getTime() > cutoff)
}

// Sets a new six-digit code on the account and returns it. Only a hash is
// stored, using the same scheme as passwords. Replaces any earlier code.
function issueVerifyCode(acct) {
  const code = String(crypto.randomInt(0, 1000000)).padStart(6, '0')
  acct.verifyCodeHash = hashPassword(code)
  acct.verifyExpires = new Date(Date.now() + VERIFY_CODE_MINUTES * 60 * 1000).toISOString()
  acct.verifyAttempts = 0
  acct.verifySends = [...recentVerifySends(acct), nowIso()]
  delete acct.verifyToken           // left over from the old verification links
  return code
}

// Creates an UNVERIFIED account. No credits are granted until the email is
// verified. Returns the verification code so the caller can email it.
function createAccount(email, password, name) {
  const db = readAll()
  const addr = String(email).trim().toLowerCase()

  const canon = canonicalEmail(addr)
  db.byCanonical = db.byCanonical || {}
  if ((db.byEmail && db.byEmail[addr]) || db.byCanonical[canon]) {
    return { ok: false, error: 'An account with this email already exists. Please log in instead.' }
  }
  if (!password || String(password).length < 8) {
    return { ok: false, error: 'Please choose a password of at least 8 characters.' }
  }
  // Name is required — it appears on correspondence and helps identify an
  // account when a payment reference arrives.
  const fullName = String(name || '').trim()
  if (fullName.length < 2) {
    return { ok: false, error: 'Please enter your full name.' }
  }

  const id = randomId('ld')

  db.accounts[id] = {
    id,
    email: addr,
    canonicalEmail: canon,
    name: fullName,
    passwordHash: hashPassword(String(password)),
    verified: false,
    balance: 0,               // nothing until verified
    createdAt: nowIso(),
    sessions: [],
    ledger: [],
    payments: [],
  }
  db.byEmail = db.byEmail || {}
  db.byEmail[addr] = id
  db.byCanonical[canon] = id
  const code = issueVerifyCode(db.accounts[id])

  writeAll(db)
  return { ok: true, account: db.accounts[id], verifyCode: code }
}

// Marks the account verified, grants the free trial credits (once only) and
// signs the customer in, so they can carry on without logging in again.
function verifyEmail(email, code) {
  const db = readAll()
  const id = db.byEmail && db.byEmail[String(email || '').trim().toLowerCase()]
  const acct = id ? db.accounts[id] : null
  const wrongCode = 'That code is not correct. Please check it and try again.'

  // Same message as a wrong code, so this can't reveal which addresses exist.
  if (!acct) return { ok: false, error: wrongCode }
  if (acct.disabled) {
    return { ok: false, error: 'This account has been suspended. Please contact support.' }
  }
  if (acct.verified) return { ok: true, account: acct, alreadyVerified: true }

  if (!acct.verifyCodeHash) {
    return { ok: false, error: 'This code is no longer valid. Please request a new one.', expired: true }
  }
  if (new Date(acct.verifyExpires) < new Date()) {
    return { ok: false, error: 'This code has expired. Please request a new one.', expired: true }
  }

  // A mistyped format doesn't use up an attempt.
  const entered = String(code || '').replace(/\s/g, '')
  if (!/^\d{6}$/.test(entered)) return { ok: false, error: 'Please enter the 6-digit code.' }

  // A six-digit code can be guessed, so each one only gets a few tries.
  acct.verifyAttempts = (acct.verifyAttempts || 0) + 1
  if (!verifyPassword(entered, acct.verifyCodeHash)) {
    if (acct.verifyAttempts >= VERIFY_MAX_ATTEMPTS) {
      acct.verifyCodeHash = null
      writeAll(db)
      return { ok: false, error: 'Too many incorrect attempts. Please request a new code.', expired: true }
    }
    writeAll(db)
    return { ok: false, error: wrongCode }
  }

  acct.verified = true
  acct.verifiedAt = nowIso()
  acct.verifyCodeHash = null
  acct.verifyExpires = null
  acct.verifyAttempts = 0

  if (FREE_TRIAL_CREDITS > 0) {
    acct.balance += FREE_TRIAL_CREDITS
    acct.ledger.push({
      at: nowIso(),
      type: 'trial',
      credits: FREE_TRIAL_CREDITS,
      note: 'Free credits on email verification',
    })
  }

  const sessionToken = createSession(acct)
  writeAll(db)
  return { ok: true, account: acct, sessionToken }
}

// Issues a fresh verification code (for "resend code"). Limited per account as
// well as per IP, so nobody can flood someone else's inbox or keep getting new
// codes to guess at.
function refreshVerifyCode(email) {
  const db = readAll()
  const id = db.byEmail && db.byEmail[String(email).trim().toLowerCase()]
  const acct = id ? db.accounts[id] : null
  if (!acct) return { ok: false, error: 'No account found with that email.' }
  if (acct.verified) return { ok: false, error: 'This email is already verified. You can log in.' }

  const sends = recentVerifySends(acct)
  if (sends.length) {
    const sinceLast = Date.now() - new Date(sends[sends.length - 1]).getTime()
    const cooldown = VERIFY_RESEND_SECONDS * 1000 - sinceLast
    if (cooldown > 0) {
      const retryAfter = Math.ceil(cooldown / 1000)
      return { ok: false, error: `Please wait ${retryAfter} seconds before requesting another code.`, retryAfter }
    }
  }
  if (sends.length >= VERIFY_MAX_SENDS_PER_HOUR) {
    const retryAfter = Math.ceil((new Date(sends[0]).getTime() + 3600 * 1000 - Date.now()) / 1000)
    return { ok: false, error: 'Too many codes requested. Please try again later.', retryAfter }
  }

  const code = issueVerifyCode(acct)
  writeAll(db)
  return { ok: true, account: acct, verifyCode: code }
}

// --- login / sessions ------------------------------------------------------

// Adds a new session to the account. The caller writes the change.
function createSession(acct) {
  const token = crypto.randomBytes(24).toString('hex')
  acct.sessions = (acct.sessions || []).filter((s) => new Date(s.expires) > new Date())
  acct.sessions.push({
    token,
    created: nowIso(),
    expires: new Date(Date.now() + SESSION_DAYS * 86400 * 1000).toISOString(),
  })
  return token
}

function login(email, password) {
  const db = readAll()
  const id = db.byEmail && db.byEmail[String(email).trim().toLowerCase()]
  const acct = id ? db.accounts[id] : null

  // Same message whether the email is unknown or the password is wrong, so the
  // form can't be used to discover which addresses are registered.
  if (!acct || !verifyPassword(String(password || ''), acct.passwordHash)) {
    return { ok: false, error: 'Email or password is incorrect.' }
  }
  // A disabled account cannot sign in, but its records are kept.
  if (acct.disabled) {
    return { ok: false, error: 'This account has been suspended. Please contact support.' }
  }
  if (!acct.verified) {
    return {
      ok: false,
      error: 'Please verify your email first. Enter the code we emailed you, or request a new one.',
      unverified: true,
      email: acct.email,
    }
  }

  const token = createSession(acct)
  writeAll(db)
  return { ok: true, account: acct, sessionToken: token }
}

// Resolves a session token to an account, or null.
function accountFromSession(token) {
  if (!token) return null
  const db = readAll()
  const acct = Object.values(db.accounts).find(
    (a) => (a.sessions || []).some((s) => s.token === token && new Date(s.expires) > new Date())
  )
  // A disabled account's live sessions stop working immediately.
  if (acct && acct.disabled) return null
  return acct || null
}

function logout(token) {
  const db = readAll()
  const acct = Object.values(db.accounts).find((a) => (a.sessions || []).some((s) => s.token === token))
  if (!acct) return { ok: true }
  acct.sessions = acct.sessions.filter((s) => s.token !== token)
  writeAll(db)
  return { ok: true }
}

// --- credits ---------------------------------------------------------------

function grantCredits(accountId, credits, reference, note) {
  const n = Math.floor(Number(credits))
  if (!Number.isFinite(n) || n <= 0) return { ok: false, error: 'Invalid credit amount' }

  const db = readAll()
  const acct = db.accounts[accountId]
  if (!acct) return { ok: false, error: 'Account not found' }
  if (!acct.verified) return { ok: false, error: 'Account email is not verified' }

  acct.balance += n
  acct.ledger.push({
    at: nowIso(),
    type: 'purchase',
    credits: n,
    amountPkr: n * PRICE_PER_CREDIT_PKR,
    reference: (reference || '').trim() || null,
    note: note || null,
  })
  writeAll(db)
  return { ok: true, account: acct }
}

// Spend one credit — called ONLY after a draft is produced successfully.
function spendCredit(accountId, documentType) {
  const db = readAll()
  const acct = db.accounts[accountId]
  if (!acct) return { ok: false, error: 'Account not found' }
  if (!acct.verified) return { ok: false, error: 'Email not verified' }
  if (acct.balance < 1) return { ok: false, error: 'Insufficient credits' }

  acct.balance -= 1
  acct.ledger.push({ at: nowIso(), type: 'draft', credits: -1, documentType: documentType || null })
  writeAll(db)
  return { ok: true, balance: acct.balance }
}

function refundCredit(accountId, reason) {
  const db = readAll()
  const acct = db.accounts[accountId]
  if (!acct) return { ok: false, error: 'Account not found' }
  acct.balance += 1
  acct.ledger.push({ at: nowIso(), type: 'refund', credits: 1, note: reason || 'Goodwill refund' })
  writeAll(db)
  return { ok: true, balance: acct.balance }
}

// --- payment proofs --------------------------------------------------------
//
// A customer transfers money, then uploads a screenshot of the transaction.
// The claim sits as "pending" until you check it against your own account and
// approve it, at which point the credits are granted in the same step.

function addPaymentClaim(accountId, claim) {
  const db = readAll()
  const acct = db.accounts[accountId]
  if (!acct) return { ok: false, error: 'Account not found' }
  if (!acct.verified) return { ok: false, error: 'Please verify your email first.' }

  acct.payments = acct.payments || []

  // Stop someone flooding the queue with unchecked submissions.
  const pending = acct.payments.filter((p) => p.status === 'pending').length
  if (pending >= 5) {
    return {
      ok: false,
      error: 'You already have several submissions awaiting review. Please wait for those to be processed.',
    }
  }

  const record = {
    id: randomId('pay'),
    at: nowIso(),
    status: 'pending',
    packageId: claim.packageId || null,
    credits: Number(claim.credits) || null,
    amountPkr: Number(claim.amountPkr) || null,
    method: claim.method || null,
    reference: (claim.reference || '').trim() || null,
    note: (claim.note || '').trim() || null,
    file: claim.file || null,          // stored filename
    originalName: claim.originalName || null,
  }
  acct.payments.push(record)
  writeAll(db)
  return { ok: true, claim: record }
}

// Every pending claim across all accounts, newest first — the admin queue.
function listPaymentClaims(status) {
  const db = readAll()
  const out = []
  for (const acct of Object.values(db.accounts)) {
    for (const p of acct.payments || []) {
      if (!status || p.status === status) {
        out.push({
          ...p,
          accountId: acct.id,
          accountEmail: acct.email,
          accountName: acct.name,
          accountBalance: acct.balance,
        })
      }
    }
  }
  return out.sort((a, b) => (a.at < b.at ? 1 : -1))
}

function findPaymentClaim(claimId) {
  const db = readAll()
  for (const acct of Object.values(db.accounts)) {
    const p = (acct.payments || []).find((x) => x.id === claimId)
    if (p) return { account: acct, claim: p }
  }
  return null
}

// Approve a claim and grant the credits in one step, so the two can never
// drift apart. `credits` overrides what the customer claimed, if given.
function approvePaymentClaim(claimId, credits, note) {
  const db = readAll()
  let target = null
  for (const acct of Object.values(db.accounts)) {
    const p = (acct.payments || []).find((x) => x.id === claimId)
    if (p) {
      target = { acct, p }
      break
    }
  }
  if (!target) return { ok: false, error: 'Payment submission not found' }
  if (target.p.status === 'approved') return { ok: false, error: 'This submission was already approved' }

  const n = Math.floor(Number(credits || target.p.credits))
  if (!Number.isFinite(n) || n <= 0) return { ok: false, error: 'Invalid credit amount' }

  target.p.status = 'approved'
  target.p.reviewedAt = nowIso()
  target.p.grantedCredits = n
  if (note) target.p.reviewNote = note

  target.acct.balance += n
  target.acct.ledger.push({
    at: nowIso(),
    type: 'purchase',
    credits: n,
    amountPkr: n * PRICE_PER_CREDIT_PKR,
    reference: target.p.reference,
    note: 'Approved payment submission ' + target.p.id,
  })

  writeAll(db)
  return { ok: true, account: target.acct, claim: target.p }
}

function rejectPaymentClaim(claimId, reason) {
  const db = readAll()
  for (const acct of Object.values(db.accounts)) {
    const p = (acct.payments || []).find((x) => x.id === claimId)
    if (p) {
      p.status = 'rejected'
      p.reviewedAt = nowIso()
      p.reviewNote = reason || 'Could not be verified'
      writeAll(db)
      return { ok: true, claim: p }
    }
  }
  return { ok: false, error: 'Payment submission not found' }
}

// --- password reset --------------------------------------------------------

const RESET_TOKEN_HOURS = 2

// Creates a reset token. Returns ok:true even when the email is unknown, so
// the form cannot be used to discover which addresses are registered — the
// caller only sends an email when a token comes back.
function createResetToken(email) {
  const db = readAll()
  const id = db.byEmail && db.byEmail[String(email || '').trim().toLowerCase()]
  const acct = id ? db.accounts[id] : null
  if (!acct) return { ok: true, account: null, token: null }

  acct.resetToken = crypto.randomBytes(24).toString('hex')
  acct.resetExpires = new Date(Date.now() + RESET_TOKEN_HOURS * 3600 * 1000).toISOString()
  writeAll(db)
  return { ok: true, account: acct, token: acct.resetToken }
}

function resetPassword(token, newPassword) {
  if (!newPassword || String(newPassword).length < 8) {
    return { ok: false, error: 'Please choose a password of at least 8 characters.' }
  }
  const db = readAll()
  const acct = Object.values(db.accounts).find((a) => a.resetToken && a.resetToken === token)
  if (!acct) return { ok: false, error: 'This reset link is not valid. Please request a new one.' }
  if (acct.resetExpires && new Date(acct.resetExpires) < new Date()) {
    return { ok: false, error: 'This reset link has expired. Please request a new one.' }
  }

  acct.passwordHash = hashPassword(String(newPassword))
  acct.resetToken = null
  acct.resetExpires = null
  // Signing out everywhere is the safe thing to do after a password change.
  acct.sessions = []
  // A password reset also proves control of the mailbox.
  if (!acct.verified) {
    acct.verified = true
    acct.verifiedAt = nowIso()
    if (FREE_TRIAL_CREDITS > 0 && !(acct.ledger || []).some((l) => l.type === 'trial')) {
      acct.balance += FREE_TRIAL_CREDITS
      acct.ledger.push({ at: nowIso(), type: 'trial', credits: FREE_TRIAL_CREDITS, note: 'Free credits on verification' })
    }
  }
  writeAll(db)
  return { ok: true, account: acct }
}

// --- saved drafts ----------------------------------------------------------
//
// A credit is spent on every draft, so the customer must be able to get it
// back. Drafts are stored against the account and can be reopened or deleted.

const MAX_SAVED_DRAFTS = 200

function saveDraft(accountId, draft) {
  const db = readAll()
  const acct = db.accounts[accountId]
  if (!acct) return { ok: false, error: 'Account not found' }

  acct.drafts = acct.drafts || []
  const record = {
    id: randomId('dr'),
    at: nowIso(),
    documentType: draft.documentType || null,
    language: draft.language || 'ur',
    isHtml: Boolean(draft.isHtml),
    title: (draft.title || '').slice(0, 160) || null,
    content: draft.content || '',
  }
  acct.drafts.push(record)
  // Keep the newest N so one account cannot grow the file without limit.
  if (acct.drafts.length > MAX_SAVED_DRAFTS) {
    acct.drafts = acct.drafts.slice(-MAX_SAVED_DRAFTS)
  }
  writeAll(db)
  return { ok: true, draft: record }
}

// Summaries only — the full text is fetched one at a time.
function listDrafts(accountId) {
  const db = readAll()
  const acct = db.accounts[accountId]
  if (!acct) return []
  return (acct.drafts || [])
    .map((d) => ({
      id: d.id,
      at: d.at,
      documentType: d.documentType,
      language: d.language,
      title: d.title,
    }))
    .reverse()
}

function getDraft(accountId, draftId) {
  const db = readAll()
  const acct = db.accounts[accountId]
  if (!acct) return null
  return (acct.drafts || []).find((d) => d.id === draftId) || null
}

function deleteDraft(accountId, draftId) {
  const db = readAll()
  const acct = db.accounts[accountId]
  if (!acct) return { ok: false, error: 'Account not found' }
  const before = (acct.drafts || []).length
  acct.drafts = (acct.drafts || []).filter((d) => d.id !== draftId)
  writeAll(db)
  return { ok: before !== acct.drafts.length }
}

function findByEmail(email) {
  const db = readAll()
  const id = db.byEmail && db.byEmail[String(email || '').trim().toLowerCase()]
  return id ? db.accounts[id] : null
}

// --- admin: account management ---------------------------------------------
//
// These power the hidden #/admin panel. They are only ever reached through
// the admin-token-guarded routes in server.js, never by a normal user. Like
// everything else here, they read/modify the JSON store and nothing else.

// Safe summary of every account, newest first. Never includes the password
// hash, tokens or sessions. `search` filters by email or name substring.
function adminListAccounts(search) {
  const db = readAll()
  const q = String(search || '').trim().toLowerCase()
  const rows = Object.values(db.accounts).map((a) => ({
    id: a.id,
    email: a.email,
    name: a.name || null,
    verified: Boolean(a.verified),
    disabled: Boolean(a.disabled),
    balance: a.balance || 0,
    createdAt: a.createdAt || null,
    draftCount: (a.drafts || []).length,
    paymentCount: (a.payments || []).length,
    pendingPayments: (a.payments || []).filter((p) => p.status === 'pending').length,
  }))
  const filtered = q
    ? rows.filter(
        (r) =>
          (r.email && r.email.toLowerCase().includes(q)) ||
          (r.name && r.name.toLowerCase().includes(q))
      )
    : rows
  return filtered.sort((a, b) => (String(a.createdAt) < String(b.createdAt) ? 1 : -1))
}

// One account in full, for the drill-in view: profile + complete ledger +
// payment history (with stored filenames so the admin can open a screenshot).
// Still no password hash, tokens or sessions.
function adminGetAccount(accountId) {
  const db = readAll()
  const a = db.accounts[accountId]
  if (!a) return null
  return {
    id: a.id,
    email: a.email,
    name: a.name || null,
    verified: Boolean(a.verified),
    verifiedAt: a.verifiedAt || null,
    disabled: Boolean(a.disabled),
    disabledAt: a.disabledAt || null,
    balance: a.balance || 0,
    createdAt: a.createdAt || null,
    ledger: (a.ledger || []).slice().reverse(),
    payments: (a.payments || [])
      .slice()
      .reverse()
      .map((p) => ({
        id: p.id,
        at: p.at,
        status: p.status,
        credits: p.credits,
        amountPkr: p.amountPkr,
        method: p.method,
        reference: p.reference,
        note: p.note,
        file: p.file,
        originalName: p.originalName,
        reviewNote: p.reviewNote || null,
        grantedCredits: p.grantedCredits || null,
      })),
    draftCount: (a.drafts || []).length,
  }
}

// Add OR subtract credits by hand. Unlike grantCredits (customer purchases,
// add-only, verified-only), an admin adjustment can be negative and works on
// any account. Balance is never allowed to go below zero. A labelled ledger
// entry records who/why so the history stays auditable.
function adminAdjustBalance(accountId, delta, note) {
  const n = Math.trunc(Number(delta))
  if (!Number.isFinite(n) || n === 0) return { ok: false, error: 'Enter a non-zero whole number.' }

  const db = readAll()
  const acct = db.accounts[accountId]
  if (!acct) return { ok: false, error: 'Account not found' }

  const before = acct.balance || 0
  const after = before + n
  if (after < 0) {
    return { ok: false, error: `That would take the balance below zero (current balance is ${before}).` }
  }

  acct.balance = after
  acct.ledger = acct.ledger || []
  acct.ledger.push({
    at: nowIso(),
    type: 'admin',
    credits: n,
    note: (note || '').trim() || 'Manual adjustment by admin',
  })
  writeAll(db)
  return { ok: true, account: acct, balance: after }
}

// Disable (suspend) an account: it can no longer log in and its live sessions
// stop working, but every record — ledger, payments, screenshots — is kept.
// Reversible with enableAccount. This is the safe default for problem accounts.
function disableAccount(accountId, reason) {
  const db = readAll()
  const acct = db.accounts[accountId]
  if (!acct) return { ok: false, error: 'Account not found' }
  acct.disabled = true
  acct.disabledAt = nowIso()
  acct.disabledReason = (reason || '').trim() || null
  acct.sessions = []                // kick them out now
  writeAll(db)
  return { ok: true, account: acct }
}

function enableAccount(accountId) {
  const db = readAll()
  const acct = db.accounts[accountId]
  if (!acct) return { ok: false, error: 'Account not found' }
  acct.disabled = false
  acct.disabledAt = null
  acct.disabledReason = null
  writeAll(db)
  return { ok: true, account: acct }
}

// Hard delete: remove the account record AND clean up the byEmail /
// byCanonical indexes so no dangling pointers remain (leaving those would
// corrupt future signups with the same address). Irreversible — the caller
// (server.js) also returns the stored screenshot filenames so they can be
// removed from disk. This is the nuclear option; disableAccount is safer.
function deleteAccount(accountId) {
  const db = readAll()
  const acct = db.accounts[accountId]
  if (!acct) return { ok: false, error: 'Account not found' }

  // Collect uploaded screenshot filenames before we drop the record, so the
  // caller can delete the files from the uploads directory.
  const files = (acct.payments || []).map((p) => p.file).filter(Boolean)

  delete db.accounts[accountId]

  // Purge every index entry that points at this id (there should be one each,
  // but we scan defensively in case an address was re-canonicalised).
  if (db.byEmail) {
    for (const [k, v] of Object.entries(db.byEmail)) {
      if (v === accountId) delete db.byEmail[k]
    }
  }
  if (db.byCanonical) {
    for (const [k, v] of Object.entries(db.byCanonical)) {
      if (v === accountId) delete db.byCanonical[k]
    }
  }

  writeAll(db)
  return { ok: true, files }
}

// What the browser is allowed to see — never the hash, tokens or sessions.
function publicView(acct) {
  if (!acct) return null
  return {
    id: acct.id,
    email: acct.email,
    name: acct.name,
    verified: acct.verified,
    balance: acct.balance,
    history: (acct.ledger || []).slice(-25).reverse(),
    payments: (acct.payments || [])
      .slice(-15)
      .reverse()
      .map((p) => ({
        id: p.id,
        at: p.at,
        status: p.status,
        credits: p.credits,
        amountPkr: p.amountPkr,
        method: p.method,
        reference: p.reference,
        originalName: p.originalName,
        reviewNote: p.reviewNote || null,
        grantedCredits: p.grantedCredits || null,
      })),
  }
}

module.exports = {
  FREE_TRIAL_CREDITS,
  PRICE_PER_CREDIT_PKR,
  PACKAGES,
  VERIFY_CODE_MINUTES,
  validateEmail,
  createAccount,
  verifyEmail,
  refreshVerifyCode,
  login,
  logout,
  accountFromSession,
  grantCredits,
  spendCredit,
  refundCredit,
  findByEmail,
  canonicalEmail,
  createResetToken,
  resetPassword,
  saveDraft,
  listDrafts,
  getDraft,
  deleteDraft,
  addPaymentClaim,
  listPaymentClaims,
  findPaymentClaim,
  approvePaymentClaim,
  rejectPaymentClaim,
  adminListAccounts,
  adminGetAccount,
  adminAdjustBalance,
  disableAccount,
  enableAccount,
  deleteAccount,
  publicView,
}